// Configure directories to monitor and thresholds
// Add more entries as needed
const config = {
  directories: [
    { path: '/var/log', warningPercent: 70, criticalPercent: 85 },
    { path: '/opt/appdata/logs', warningPercent: 60, criticalPercent: 80 },
    { path: '/home/docker/logs', warningPercent: 70, criticalPercent: 85 },
  ],
  };

const config = $items('Configure Directories')[0].json;
const raw = $items('Check Disk Usage')[0].json.stdout;
const lines = raw.trim().split('\n');

const results = [];
let hasAlert = false;

for (const line of lines) {
  const parts = line.trim().split(/\s+/);
  if (parts.length < 4) continue;
  const [dirPath, usedKb, usedTotalKb, availKb] = parts;
  const totalKb = parseInt(usedTotalKb) + parseInt(availKb);
  const percent = totalKb > 0 ? Math.round((parseInt(usedKb) / totalKb) * 100) : 0;
  const dirConfig = config.directories.find(d => d.path === dirPath);
  if (!dirConfig) continue;

  let level = '🟢';
  if (percent >= dirConfig.criticalPercent) { level = '🔴'; hasAlert = true; }
  else if (percent >= dirConfig.warningPercent) { level = '🟡'; hasAlert = true; }

  const barLength = 10;
  const filled = Math.round((percent / 100) * barLength);
  const bar = '█'.repeat(filled) + '░'.repeat(barLength - filled);

  results.push(`${level} ${dirPath}: ${(parseInt(usedKb)/1024).toFixed(1)} MB used (${percent}%) \`${bar}\``);
}

const now = new Date().toISOString().split('T')[0];
const title = hasAlert ? '⚠️ Log Disk Usage Alert' : '🟢 Log Disk Check';
const message = `${title} — ${now}\n\n${results.join('\n')}`;

return [{ json: { message, hasAlert } }];
